using Majorsilence.Reporting.Data;
using NUnit.Framework;
using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Linq;
using System.Text;

namespace ReportTests
{
    /// <summary>
    /// Pins what XmlDataReader returns for a range of documents and commands. The expected text was
    /// generated by the original XPathDocument based implementation, so the streaming reader (and the
    /// compiled column expressions) must match it, including the cases that fall back to XPath.
    /// </summary>
    [TestFixture]
    public class XmlReaderShapeTests
    {
        static readonly string Rows3 = "<rows><row><Id>1</Id><Name>a</Name></row><row><Id>2</Id><Name>b</Name></row><row><Id>3</Id><Name>c</Name></row></rows>";

        public static readonly (string Name, string Xml, string Command)[] Cases =
        [
            ("elements", Rows3, "RowsXPath=/rows/row"),
            ("elements-type", Rows3, "RowsXPath=/rows/row;Type=elements"),
            ("relative-path", Rows3, "RowsXPath=rows/row"),
            ("attributes", """<rows><row id="1" name="a"/><row id="2" name="b"/></rows>""", "RowsXPath=/rows/row;Type=attributes"),
            ("both", """<rows><row id="1"><name>a</name></row><row id="2"><name>b</name></row></rows>""", "RowsXPath=/rows/row;Type=both"),
            ("both-name-clash", """<rows><row id="1"><id>x</id></row><row id="2"><id>y</id></row></rows>""", "RowsXPath=/rows/row;Type=both"),
            ("pretty-printed", "<rows>\n  <row>\n    <Id> 1 </Id>\n    <Name>a b</Name>\n  </row>\n  <row>\n    <Id>2</Id>\n    <Name>  </Name>\n  </row>\n</rows>", "RowsXPath=/rows/row"),
            ("xml-space-preserve", "<rows><row><a xml:space=\"preserve\">  </a><b>  </b></row></rows>", "RowsXPath=/rows/row"),
            ("nested-value", "<rows><row><a>x<b>y</b>z</a><c><d><e>deep</e></d></c></row></rows>", "RowsXPath=/rows/row"),
            ("cdata-entities", "<rows><row><a><![CDATA[<raw & text>]]></a><b>&amp; &lt; &#65; &#x42;</b><c>p<!-- note -->q<?pi x?>r</c></row></rows>", "RowsXPath=/rows/row"),
            ("empty-elements", "<rows><row><a/><b></b><c> </c></row></rows>", "RowsXPath=/rows/row"),
            ("missing-and-extra", "<rows><row><a>1</a><b>2</b></row><row><b>3</b></row><row><a>4</a><b>5</b><c>6</c></row></rows>", "RowsXPath=/rows/row"),
            ("duplicate-children", "<rows><row><a>1</a><a>2</a><b>3</b></row><row><a>4</a><a>5</a><b>6</b></row></rows>", "RowsXPath=/rows/row"),
            ("default-namespace-root", "<rows xmlns=\"urn:x\"><row><a>1</a></row></rows>", "RowsXPath=/rows/row"),
            ("default-namespace-child", "<rows><row xmlns=\"urn:x\"><a>1</a></row><row><a>2</a></row></rows>", "RowsXPath=/rows/row"),
            ("prefixed-children", "<rows xmlns:p=\"urn:p\"><row><p:a>1</p:a><b>2</b></row><row><p:a>3</p:a><b>4</b></row></rows>", "RowsXPath=/rows/row"),
            ("prefixed-attributes", "<rows xmlns:p=\"urn:p\"><row p:a=\"1\" b=\"2\"/></rows>", "RowsXPath=/rows/row;Type=attributes"),
            ("xmlns-attributes", "<rows><row xmlns:p=\"urn:p\" xmlns=\"urn:d\" a=\"1\"/></rows>", "RowsXPath=/rows/row;Type=attributes"),
            ("columns-simple", Rows3, "RowsXPath=/rows/row;ColumnsXPath=Name,Id"),
            ("columns-missing-first-row", "<rows><row><a>1</a></row><row><a>2</a><b>3</b></row></rows>", "RowsXPath=/rows/row;ColumnsXPath=b,a"),
            ("columns-attribute", """<rows><row id="1"><n>a</n></row><row id="2"><n>b</n></row></rows>""", "RowsXPath=/rows/row;ColumnsXPath=@id,n,@zz"),
            ("columns-duplicates", Rows3, "RowsXPath=/rows/row;ColumnsXPath=Id,Id,Name"),
            ("columns-parent", "<r><t>T</t><rows><row><a>1</a></row></rows></r>", "RowsXPath=/r/rows/row;ColumnsXPath=a,../../t"),
            ("columns-function", Rows3, "RowsXPath=/rows/row;ColumnsXPath=Id,string-length(Name)"),
            ("rows-descendant", "<r><a><row><x>1</x></row></a><row><x>2</x></row></r>", "RowsXPath=//row"),
            ("rows-predicate", Rows3, "RowsXPath=/rows/row[2]"),
            ("rows-wildcard", Rows3, "RowsXPath=/rows/*"),
            ("deep-path", "<a><b><c><row><x>1</x></row></c><row><x>no</x></row></b><c><row><x>2</x></row></c></a>", "RowsXPath=/a/b/c/row"),
            ("rows-at-other-depths", "<rows><row><x>1</x><row><x>nested</x></row></row><sub><row><x>2</x></row></sub></rows>", "RowsXPath=/rows/row"),
            ("no-rows", "<rows/>", "RowsXPath=/rows/row"),
            ("wrong-root", "<other><row><x>1</x></row></other>", "RowsXPath=/rows/row"),
            ("doctype-entity", "<!DOCTYPE rows [<!ENTITY e \"expanded\">]><rows><row><a>&e;</a></row></rows>", "RowsXPath=/rows/row"),
            ("text-in-row", "<rows><row>stray<a>1</a>more</row></rows>", "RowsXPath=/rows/row"),
            ("unicode", "<rows><row><a>h\u00e9llo \U0001F600</a></row></rows>", "RowsXPath=/rows/row"),
            ("hyphen-dot-names", "<rows><row><first-name>a</first-name><my.val>b</my.val></row></rows>", "RowsXPath=/rows/row"),
            ("malformed", "<rows><row><a>1</a></rows>", "RowsXPath=/rows/row"),
        ];

        static string Dump(string xml, string command, int readers = 2)
        {
            string path = Path.Combine(Path.GetTempPath(), "rdl-xmlshape-" + Guid.NewGuid().ToString("N") + ".xml");
            File.WriteAllText(path, xml, new UTF8Encoding(false));
            var sb = new StringBuilder();
            try
            {
                using var cn = new XmlConnection("file=" + path);
                cn.Open();
                using var cmd = cn.CreateCommand();
                cmd.CommandText = "Url=" + path + ";" + command;
                // a second reader on the same command sees the columns the first one stored on it
                for (int r = 0; r < readers; r++)
                {
                    sb.Append("reader ").AppendLine((r + 1).ToString());
                    try
                    {
                        using var dr = cmd.ExecuteReader(CommandBehavior.SingleResult);
                        sb.Append("  cols=").AppendLine(string.Join(",", Enumerable.Range(0, dr.FieldCount).Select(i => dr.GetName(i) + ":" + dr.GetFieldType(i).Name)));
                        while (dr.Read())
                        {
                            var vals = new object[dr.FieldCount];
                            dr.GetValues(vals);
                            sb.Append("  ").AppendLine(string.Join(" | ", vals.Select(v => v == null ? "NULL" : "'" + v.ToString().Replace("\n", "\\n").Replace("\r", "\\r") + "'")));
                        }
                    }
                    catch (Exception e)
                    {
                        sb.Append("  EXCEPTION ").AppendLine(e.GetType().Name);
                    }
                }
            }
            finally
            {
                File.Delete(path);
            }
            return sb.ToString();
        }

        [Test]
        public void Rows_MatchTheXPathImplementation()
        {
            string dumpTo = Environment.GetEnvironmentVariable("XML_GOLDEN_OUT");
            var all = new StringBuilder();
            foreach (var (name, xml, command) in Cases)
                all.Append("### ").AppendLine(name).Append(Dump(xml, command)).AppendLine();

            if (!string.IsNullOrEmpty(dumpTo))
            {
                File.WriteAllText(dumpTo, all.ToString());
                Assert.Pass("golden written");
            }

            Assert.That(all.ToString().Replace("\r\n", "\n").TrimEnd(), Is.EqualTo(XmlReaderGolden.Text.Replace("\r\n", "\n").TrimEnd()));
        }

        [Test]
        public void StreamedFile_IsNotLockedOnceTheRowsAreRead()
        {
            string path = Path.Combine(Path.GetTempPath(), "rdl-xmlshape-" + Guid.NewGuid().ToString("N") + ".xml");
            File.WriteAllText(path, Rows3);
            try
            {
                using var cn = new XmlConnection("file=" + path);
                cn.Open();
                using var cmd = cn.CreateCommand();
                cmd.CommandText = "Url=" + path + ";RowsXPath=/rows/row";
                var dr = cmd.ExecuteReader(CommandBehavior.SingleResult);   // deliberately not disposed
                while (dr.Read()) { }
                Assert.DoesNotThrow(() => File.Delete(path));
            }
            finally
            {
                if (File.Exists(path)) File.Delete(path);
            }
        }

        // the shape tests prove the results match; this proves the cheap path is the one being taken
        [TestCase("RowsXPath=/rows/row", true)]
        [TestCase("RowsXPath=/rows/row;Type=attributes", true)]
        [TestCase("RowsXPath=/rows/row;ColumnsXPath=Name,Id", true)]
        [TestCase("RowsXPath=//row", false)]
        [TestCase("RowsXPath=/rows/row[1]", false)]
        [TestCase("RowsXPath=/rows/row;ColumnsXPath=Id,../x", false)]
        public void SimplePaths_AreStreamed(string command, bool streamed)
        {
            string path = Path.Combine(Path.GetTempPath(), "rdl-xmlshape-" + Guid.NewGuid().ToString("N") + ".xml");
            File.WriteAllText(path, Rows3);
            try
            {
                using var cn = new XmlConnection("file=" + path);
                cn.Open();
                using var cmd = cn.CreateCommand();
                cmd.CommandText = "Url=" + path + ";" + command;
                using var dr = cmd.ExecuteReader(CommandBehavior.SingleResult);
                var field = typeof(XmlDataReader).GetField("_stream", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                Assert.That(field.GetValue(dr) != null, Is.EqualTo(streamed));
            }
            finally
            {
                File.Delete(path);
            }
        }

        [Test]
        public void PrefetchedText_IsStreamed()
        {
            using var cn = new XmlConnection("file=unused");
            cn.Open();
            using var cmd = cn.CreateCommand();
            cmd.CommandText = "Url=http://127.0.0.1:1/never-fetched;RowsXPath=/rows/row";
            // the document comes from the constructor argument, not the url
            var ctor = typeof(XmlDataReader).GetConstructors(System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)
                .Single(c => c.GetParameters().Length == 4);
            using var dr = (XmlDataReader)ctor.Invoke(new object[] { CommandBehavior.SingleResult, cn, cmd, Rows3 });
            int rows = 0;
            while (dr.Read()) rows++;
            Assert.That(rows, Is.EqualTo(3));
        }
    }
}
